$imp=new CsvImporter();$arrays=CsvImporter::arrayFields();$w=$_SESSION['_hardware_wizard']??['records'=>[]];$err=null;$labels=['ComputerName'=>'نام کامپیوتر','UserName'=>'کاربر','Manufacturer'=>'سازنده','Model'=>'مدل','SystemType'=>'نوع سیستم','SystemSerial'=>'سریال سیستم','SystemUUID'=>'UUID','Domain'=>'دامین / Workgroup','OSName'=>'سیستم‌عامل','OSVersion'=>'نسخه سیستم‌عامل','OSBuild'=>'Build','OSArchitecture'=>'معماری','CPUName'=>'پردازنده','CPUManufacturer'=>'سازنده CPU','CPUCores'=>'هسته فیزیکی','CPULogicalProcessors'=>'پردازنده منطقی','CPUMaxClockMHz'=>'فرکانس CPU (MHz)','RAMTotalGB'=>'RAM کل (GB)','RAMSlotCount'=>'تعداد اسلات RAM','RAMInstalledSlots'=>'اسلات‌های پر','RAMManufacturers'=>'سازندگان RAM','RAMPartNumbers'=>'Part Numberهای RAM','RAMSerialNumbers'=>'سریال‌های RAM','RAMSpeedsMHz'=>'فرکانس RAM','RAMType'=>'نوع RAM','RAMSlotDetails'=>'جزئیات اسلات RAM','MotherboardManufacturer'=>'سازنده مادربرد','MotherboardProduct'=>'مدل مادربرد','MotherboardVersion'=>'نسخه مادربرد','MotherboardSerial'=>'سریال مادربرد','BIOSManufacturer'=>'سازنده BIOS','BIOSVersion'=>'نسخه BIOS','BIOSSerial'=>'سریال BIOS','BIOSReleaseDate'=>'تاریخ BIOS','DiskDetails'=>'دیسک‌های فیزیکی','LogicalDriveDetails'=>'درایوهای منطقی','NetworkDetails'=>'جزئیات کارت‌های شبکه','MACAddresses'=>'MAC','IPAddresses'=>'IP','SubnetMasks'=>'Subnet Mask','Gateways'=>'Gateway','DNSServers'=>'DNS','GPUDetails'=>'کارت گرافیک','SoundDetails'=>'کارت صدا','MonitorDetails'=>'نمایشگر','PageFileDetails'=>'Page File','AntivirusDetails'=>'آنتی‌ویروس','BootCount'=>'تعداد بوت','NormalShutdownCount'=>'خاموشی عادی','UnexpectedShutdownCount'=>'خاموشی غیرمنتظره','UserShutdownCount'=>'خاموشی کاربر','LastBootTime'=>'آخرین روشن‌شدن','LastShutdownTime'=>'آخرین خاموش‌شدن','CompletedSessionCount'=>'جلسات کامل','CurrentSessionHours'=>'جلسه فعلی (ساعت)','CurrentSessionDuration'=>'مدت جلسه فعلی','TotalUsageHours'=>'کل استفاده (ساعت)','TotalUsageDuration'=>'کل مدت استفاده','AverageSessionHours'=>'میانگین جلسه (ساعت)','AverageSessionDuration'=>'میانگین مدت جلسه','LongestSessionHours'=>'طولانی‌ترین جلسه (ساعت)','LongestSessionDuration'=>'طولانی‌ترین جلسه','CollectedAt'=>'زمان جمع‌آوری','PrinterType'=>'نوع چاپگر','PrinterCapabilities'=>'قابلیت‌ها','ColorMode'=>'رنگی/سیاه‌وسفید','Connection'=>'نوع اتصال','NetworkSharing'=>'اشتراک‌گذاری شبکه','Duplex'=>'چاپ دورو','DisplayTechnology'=>'فناوری نمایشگر','DisplaySize'=>'اندازه نمایشگر','DisplayResolution'=>'رزولوشن','DisplaySerial'=>'سریال نمایشگر','ScannerType'=>'نوع اسکنر','ScannerResolution'=>'رزولوشن اسکنر','ScannerConnection'=>'اتصال اسکنر','ScannerDuplex'=>'اسکن دورو'];
