if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');if($action==='reset'){unset($_SESSION['_hardware_wizard']);redirect('asset_wizard.php');}if($step!=='review'&&$action==='analyze'){if(empty($_FILES['csv']['tmp_name'])||$_FILES['csv']['error']!==UPLOAD_ERR_OK)$err='فایل CSV انتخاب نشده است.';elseif(strtolower(pathinfo($_FILES['csv']['name'],PATHINFO_EXTENSION))!=='csv')$err='فقط CSV مجاز است.';else try{$g=$imp->rows($_FILES['csv']['tmp_name']);$r=$g->current();if(!$r)throw new RuntimeException('فایل داده‌ای ندارد.');if(in_array($step,['printer','scanner'],true)){$r['IPAddresses']=[];unset($r['MACAddresses']);}$r['_source_file']=basename($_FILES['csv']['name']);$w['records'][$step]=$r;$_SESSION['_hardware_wizard']=$w;redirect('asset_wizard.php?step='.$step);}catch(Throwable $e){$err=$e->getMessage();}}
if($step!=='review'&&$action==='next'){$r=$w['records'][$step]??[];foreach((array)($_POST['technical']??[]) as $k=>$v){$txt=trim((string)$v);if(in_array($k,$arrays,true)){$d=json_decode($txt,true);$r[$k]=(json_last_error()===JSON_ERROR_NONE&&is_array($d))?array_values($d):$imp->split($txt);}else$r[$k]=$txt;}$r['asset_no']=trim((string)($_POST['asset_no']??''));$r['location']=trim((string)($_POST['location']??''));$r['personnel_id']=trim((string)($_POST['personnel_id']??''));if(!preg_match('/^\d{7}$/',$r['asset_no']))$err='شماره اموال باید دقیقاً ۷ رقم باشد.';elseif($r['location']==='')$err='مکان الزامی است.';else{$w['records'][$step]=$r;$_SESSION['_hardware_wizard']=$w;$i=array_search($step,$steps,true);redirect($i<count($steps)-1?'asset_wizard.php?step='.$steps[$i+1]:'asset_wizard.php?step=review');}}
if($step==='review'&&$action==='finish'){if(count(array_intersect($steps,array_keys($w['records'])))<4)$err='ابتدا هر چهار مرحله را تکمیل کنید.';else try{$seen=[];foreach($steps as $s){$no=$w['records'][$s]['asset_no']??'';if(!preg_match('/^\d{7}$/',$no))throw new RuntimeException('شماره اموال '.$types[$s].' نامعتبر است.');if(isset($seen[$no]))throw new RuntimeException('شماره اموال '.$no.' تکراری است.');$seen[$no]=1;$q=db()->prepare('SELECT asset_no FROM assets WHERE asset_no=?');$q->execute([$no]);if($q->fetchColumn())throw new RuntimeException('شماره اموال '.$no.' قبلاً ثبت شده است.');}db()->beginTransaction();$usage=['BootCount'=>'boot_count','NormalShutdownCount'=>'normal_shutdown_count','UnexpectedShutdownCount'=>'unexpected_shutdown_count','UserShutdownCount'=>'user_shutdown_count','LastBootTime'=>'last_boot_time','LastShutdownTime'=>'last_shutdown_time','CompletedSessionCount'=>'completed_session_count','CurrentSessionHours'=>'current_session_hours','CurrentSessionDuration'=>'current_session_duration','TotalUsageHours'=>'total_usage_hours','TotalUsageDuration'=>'total_usage_duration','AverageSessionHours'=>'average_session_hours','AverageSessionDuration'=>'average_session_duration','LongestSessionHours'=>'longest_session_hours','LongestSessionDuration'=>'longest_session_duration','CollectedAt'=>'collected_at'];foreach($steps as $s){$r=$w['records'][$s];$tech=[];foreach($r as $k=>$v)if($k[0]!=='_'&&!in_array($k,['asset_no','location','personnel_id'],true))$tech[$k]=$v;$cols=['asset_no','asset_type','device_subtype','hostname','personnel_id','location','department','manufacturer','model','serial_no','technical','status','source_file','created_by','updated_by'];$vals=[$r['asset_no'],$s,$r['device_subtype']??null,$r['ComputerName']??$r['PrinterName']??$r['ScannerName']??$r['DisplayName']??null,($r['personnel_id']??'')!==''?(int)$r['personnel_id']:null,$r['location'],null,$r['Manufacturer']??$r['PrinterManufacturer']??$r['ScannerManufacturer']??$r['DisplayManufacturer']??'', $r['Model']??$r['PrinterModel']??$r['ScannerModel']??$r['DisplayModel']??'', $r['SystemSerial']??$r['PrinterSerial']??$r['ScannerSerial']??$r['DisplaySerial']??'',json_encode($tech,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE),'active',$r['_source_file']??null,user()['id'],user()['id']];foreach($usage as $src=>$col){$cols[]=$col;$vals[]=($r[$src]??'')===''?null:$r[$src];}$marks=implode(',',array_fill(0,count($cols),'?'));db()->prepare('INSERT INTO assets('.implode(',',$cols).') VALUES('.$marks.')')->execute($vals);foreach($imp->disks($r) as $d)db()->prepare('INSERT INTO asset_disks(asset_no,disk_index,model,size_gb,serial_no,interface_name,media) VALUES(?,?,?,?,?,?,?)')->execute([$r['asset_no'],$d['index'],$d['model'],$d['size_gb'],$d['serial_no'],$d['interface']??null,$d['media']??null]);foreach($imp->ramSlots($r) as $x)db()->prepare('INSERT INTO asset_ram_slots(asset_no,slot_no,state,capacity_gb,ram_type,speed_mhz,manufacturer,part_number,serial_no) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$r['asset_no'],$x['slot_no'],$x['state']??'unknown',$x['capacity_gb']??null,$x['ram_type']??null,$x['speed_mhz']??null,$x['manufacturer']??null,$x['part_number']??null,$x['serial_no']??null]);audit('hardware_wizard_asset_created','asset',$r['asset_no'],['type'=>$s,'source'=>$r['_source_file']??null]);}db()->commit();unset($_SESSION['_hardware_wizard']);flash('success','هر چهار پایگاه با موفقیت ثبت شدند.');redirect('index.php');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$err=$e->getMessage();}}
}
