?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ثبت مرحله‌ای تجهیزات</title><link rel="stylesheet" href="assets/app.css"></head><body><header><a class="brand" href="index.php">سامانه سخت‌افزار</a><nav><a href="index.php">داشبورد</a><a href="assets.php">تجهیزات</a><a href="report.php">گزارش‌ها</a><?php if((user()['role']??'')==='admin'):?><a href="users.php">کاربران</a><a href="directory.php">Active Directory</a><?php endif;?><a href="logout.php">خروج</a></nav></header><main><div class="page-head"><div><div class="eyebrow">ثبت یکپارچه چهار پایگاه</div><h1><?=$step==='review'?'تأیید نهایی':'تحلیل '.$types[$step]?></h1><p class="muted">چهار فایل مرحله‌به‌مرحله خوانده می‌شوند و ثبت قطعی فقط پس از تأیید نهایی انجام می‌شود.</p></div></div><div class="wizard-steps"><?php foreach($steps as $s):?><a class="wizard-step <?=isset($w['records'][$s])?'done':''?> <?=$step===$s?'active':''?>" href="asset_wizard.php?step=<?=$s?>"><b><?=array_search($s,$steps)+1?></b><span><?=$types[$s]?></span></a><?php endforeach;?><a class="wizard-step <?=$step==='review'?'active':''?>" href="asset_wizard.php?step=review"><b>✓</b><span>تأیید نهایی</span></a></div><?php if($err):?><div class="alert danger"><?=e($err)?></div><?php endif;?><?php if($step==='review'):?><section class="review-grid"><?php foreach($steps as $s):$r=$w['records'][$s]??[];?><article class="panel review-card"><div class="section-title"><h2><?=$types[$s]?></h2><a class="btn small" href="asset_wizard.php?step=<?=$s?>">ویرایش</a></div><div class="review-fields"><div><span>شماره اموال</span><strong><?=e($r['asset_no']??'—')?></strong></div><div><span>مدل</span><strong><?=e($r['Model']??$r['PrinterModel']??$r['ScannerModel']??$r['DisplayModel']??'—')?></strong></div><div><span>مکان</span><strong><?=e($r['location']??'—')?></strong></div><div><span>فایل</span><strong><?=e($r['_source_file']??'—')?></strong></div></div></article><?php endforeach;?></section><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="step" value="review"><div class="actions sticky-confirm"><button class="btn primary" name="action" value="finish">✓ تأیید نهایی و ثبت همه</button><button class="btn" name="action" value="reset">شروع مجدد</button></div></form><?php else:$r=$w['records'][$step]??[];$people=db()->query('SELECT id,full_name,personnel_code FROM personnel ORDER BY full_name LIMIT 5000')->fetchAll();?><section class="panel"><h2>۱. بارگذاری و تحلیل <?=$types[$step]?></h2><form method="post" enctype="multipart/form-data" class="upload-row"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="step" value="<?=$step?>"><input type="hidden" name="action" value="analyze"><input type="file" name="csv" accept=".csv,text/csv" required><button class="btn" type="submit">تحلیل CSV</button></form><?php if(isset($r['_source_file'])):?><p class="muted">فایل تحلیل‌شده: <?=e($r['_source_file'])?></p><?php endif;?></section><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="step" value="<?=$step?>"><div class="actions wizard-confirm-top"><button class="btn primary" name="action" value="next">ذخیره مرحله و ادامه</button></div><section class="panel"><h2>۲. تکمیل و ویرایش</h2><div class="form-grid three-cols"><label>شماره اموال *<input name="asset_no" value="<?=e($r['asset_no']??'')?>" maxlength="7" pattern="\d{7}" required></label><label>مکان *<input name="location" value="<?=e($r['location']??'')?>" required></label><?php if($step==='computer'):?><label>پرسنل<select name="personnel_id"><option value="">انتخاب پرسنل</option><?php foreach($people as $p):?><option value="<?=$p['id']?>" <?=((string)($r['personnel_id']??'')===(string)$p['id'])?'selected':''?>><?=e($p['full_name'].' — '.$p['personnel_code'])?></option><?php endforeach;?></select></label><?php endif;?></div><div class="wizard-fields"><?php foreach($r as $k=>$v):if($k[0]==='_'||in_array($k,['asset_no','location','personnel_id'],true))continue;if(in_array($step,['printer','scanner'],true)&&$k==='MACAddresses')continue;?><label><?=e(wl($k))?><textarea name="technical[<?=e($k)?>]" rows="<?=in_array($k,$arrays,true)||in_array($k,['NetworkDetails','RAMSlotDetails','DiskDetails','LogicalDriveDetails'],true)?'4':'2'?>" <?=in_array($k,$arrays,true)?'dir="ltr"':''?>><?=e(wv($v))?></textarea></label><?php endforeach;?></div></section><div class="actions sticky-confirm"><button class="btn primary" name="action" value="next">ذخیره مرحله و ادامه</button><button class="btn" name="action" value="reset">شروع مجدد</button></div></form><?php endif;?></main></body></html>
